package com.argus.security.jwt;

/**
 * Public, intentionally non-secret development key pairs. Production construction rejects every
 * fallback in this class. Keeping the pair deterministic lets separate zero-infra demo processes
 * interoperate without checking a misleading "secret" file into the repository.
 */
final class DemoKeyMaterial {

    private DemoKeyMaterial() {
    }

    static String keyId(KeyPurpose purpose) {
        return purpose == KeyPurpose.AUTH ? "demo-auth-v1" : "demo-workload-v1";
    }

    static String privateKeys(KeyPurpose purpose) {
        return keyId(purpose) + ":" + (purpose == KeyPurpose.AUTH ? AUTH_PRIVATE : WORKLOAD_PRIVATE);
    }

    static String publicKeys(KeyPurpose purpose) {
        return keyId(purpose) + ":" + (purpose == KeyPurpose.AUTH ? AUTH_PUBLIC : WORKLOAD_PUBLIC);
    }

    private static final String AUTH_PRIVATE = "";
    private static final String AUTH_PUBLIC = "";
    private static final String WORKLOAD_PRIVATE = "";
    private static final String WORKLOAD_PUBLIC = "";
}
